//! Port of acorn 8.19.0 `src/identifier.js`.
//!
//! SVELTERS: the "big ugly regular expressions" are expanded into sorted range tables
//! (`generated.rs`, regenerated by `gen/gen_identifier_tables.mjs`) and binary-searched.
//! Reserved word / keyword lists are matched with `match` instead of `wordsRegexp`.

use super::generated::{
    ASTRAL_IDENTIFIER_CODES, ASTRAL_IDENTIFIER_START_CODES, NON_ASCII_IDENTIFIER, NON_ASCII_IDENTIFIER_START,
};

// Reserved word lists for various dialects of the language

/// `reservedWords[3]`
pub fn is_reserved_3(w: &str) -> bool {
    matches!(
        w,
        "abstract" | "boolean" | "byte" | "char" | "class" | "double" | "enum" | "export" | "extends" | "final"
            | "float" | "goto" | "implements" | "import" | "int" | "interface" | "long" | "native" | "package"
            | "private" | "protected" | "public" | "short" | "static" | "super" | "synchronized" | "throws"
            | "transient" | "volatile"
    )
}

/// `reservedWords[5]`
pub fn is_reserved_5(w: &str) -> bool {
    matches!(w, "class" | "enum" | "extends" | "super" | "const" | "export" | "import")
}

/// `reservedWords[6]`
pub fn is_reserved_6(w: &str) -> bool {
    w == "enum"
}

/// `reservedWords.strict`
pub fn is_reserved_strict(w: &str) -> bool {
    matches!(w, "implements" | "interface" | "let" | "package" | "private" | "protected" | "public" | "static" | "yield")
}

/// `reservedWords.strictBind`
pub fn is_reserved_strict_bind(w: &str) -> bool {
    matches!(w, "eval" | "arguments")
}

// And the keywords

/// `ecma5AndLessKeywords`
pub fn is_ecma5_and_less_keyword(w: &str) -> bool {
    matches!(
        w,
        "break" | "case" | "catch" | "continue" | "debugger" | "default" | "do" | "else" | "finally" | "for"
            | "function" | "if" | "return" | "switch" | "throw" | "try" | "var" | "while" | "with" | "null"
            | "true" | "false" | "instanceof" | "typeof" | "void" | "delete" | "new" | "in" | "this"
    )
}

/// Which `keywords` list a parser uses (`5`, `"5module"`, `6`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum KeywordSet {
    Es5,
    Es5Module,
    Es6,
}

pub fn is_keyword(set: KeywordSet, w: &str) -> bool {
    if is_ecma5_and_less_keyword(w) {
        return true;
    }
    match set {
        KeywordSet::Es5 => false,
        KeywordSet::Es5Module => matches!(w, "export" | "import"),
        KeywordSet::Es6 => matches!(w, "const" | "class" | "extends" | "export" | "import" | "super"),
    }
}

/// `keywordRelationalOperator = /^in(stanceof)?$/`
pub fn is_keyword_relational_operator(w: &str) -> bool {
    w == "in" || w == "instanceof"
}

// ## Character categories

fn in_bmp_ranges(code: u32, ranges: &[(u16, u16)]) -> bool {
    let code = code as u16;
    ranges
        .binary_search_by(|&(lo, hi)| {
            if hi < code {
                std::cmp::Ordering::Less
            } else if lo > code {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

// This has a complexity linear to the value of the code. The
// assumption is that looking up astral identifier characters is
// rare.
fn is_in_astral_set(code: u32, set: &[u32]) -> bool {
    let mut pos: u32 = 0x10000;
    let mut i = 0;
    while i + 1 < set.len() {
        pos += set[i];
        if pos > code {
            return false;
        }
        pos += set[i + 1];
        if pos >= code {
            return true;
        }
        i += 2;
    }
    false
}

// Test whether a given character code starts an identifier.

pub fn is_identifier_start(code: u32, astral: bool) -> bool {
    if code < 65 {
        return code == 36;
    }
    if code < 91 {
        return true;
    }
    if code < 97 {
        return code == 95;
    }
    if code < 123 {
        return true;
    }
    if code <= 0xffff {
        return code >= 0xaa && in_bmp_ranges(code, NON_ASCII_IDENTIFIER_START);
    }
    if !astral {
        return false;
    }
    is_in_astral_set(code, ASTRAL_IDENTIFIER_START_CODES)
}

// Test whether a given character is part of an identifier.

pub fn is_identifier_char(code: u32, astral: bool) -> bool {
    if code < 48 {
        return code == 36;
    }
    if code < 58 {
        return true;
    }
    if code < 65 {
        return false;
    }
    if code < 91 {
        return true;
    }
    if code < 97 {
        return code == 95;
    }
    if code < 123 {
        return true;
    }
    if code <= 0xffff {
        return code >= 0xaa && in_bmp_ranges(code, NON_ASCII_IDENTIFIER);
    }
    if !astral {
        return false;
    }
    is_in_astral_set(code, ASTRAL_IDENTIFIER_START_CODES) || is_in_astral_set(code, ASTRAL_IDENTIFIER_CODES)
}
